1	package cli
2	
3	import (
4		"context"
5		"crypto/rand"
6		"encoding/hex"
7		"errors"
8		"fmt"
9		"os"
10		"path/filepath"
11		"runtime"
12		"strings"
13		"time"
14	
15		"golang.org/x/mod/semver"
16	)
17	
18	// Remote install orchestration: resolve tag → fetch metadata → download +
19	// verify + extract → place under pkg/<name>/ → link into bin/ → write
20	// manifest. The bin/ link goes through the same InstallPluginFromPath used
21	// by local-dev installs, so conflict handling, atomic replace, and the
22	// Windows symlink fallbacks are shared, not duplicated.
23	
24	// maxTagFallbacks bounds how many tags we walk down when the newest tag has
25	// no published assets (tag pushed, release not finished).
26	const maxTagFallbacks = 3
27	
28	// RemoteInstallOptions configures InstallPluginFromRepo.
29	type RemoteInstallOptions struct {
30		// RepoURL is the full git URL of the plugin repository.
31		RepoURL string
32		// Pin, when non-empty, installs exactly this tag and marks the
33		// manifest pinned so upgrade skips it.
34		Pin string
35		// Force replaces an existing managed entry with the same name.
36		Force bool
37		// AllowUnverified permits installing a release that publishes no
38		// checksums.txt covering this platform. Off by default: downloading and
39		// executing an unauthenticated binary is the supply-chain risk the
40		// checksum path exists to remove, so it takes an explicit opt-in.
41		AllowUnverified bool
42		// ExpectedName is the plugin name the caller has already committed to —
43		// the index entry the user asked for, the requirement being satisfied, or
44		// the plugin being upgraded. Empty only when the caller genuinely has no
45		// expectation, i.e. a bare `install <url>` where the repository names
46		// itself. See installRepoAtTag for why a mismatch is fatal.
47		ExpectedName string
48	}
49	
50	// RemoteInstallResult is what a successful remote install produced.
51	type RemoteInstallResult struct {
52		Installed *InstalledPlugin
53		Manifest  *PluginManifest
54		Metadata  *PluginMetadata
55		// SkippedTags lists newer tags that were passed over for missing
56		// assets, newest first. Callers surface these as warnings.
57		SkippedTags []string
58	}
59	
60	// InstallPluginFromRepo installs a plugin from a git repository URL.
61	// Dependency resolution deliberately does not happen here — callers
62	// (the install command) plan and confirm dependency installs first.
63	func InstallPluginFromRepo(ctx context.Context, opts RemoteInstallOptions) (*RemoteInstallResult, error) {
64		repoURL := strings.TrimRight(opts.RepoURL, "/")
65	
66		var tags []string
67		if opts.Pin != "" {
68			tags = []string{opts.Pin}
69		} else {
70			var err error
71			tags, err = listRemoteSemverTags(ctx, repoURL)
72			if err != nil {
73				return nil, err
74			}
75			if len(tags) == 0 {
76				return nil, fmt.Errorf("%s has no stable semver tags; prereleases are skipped, so pass --pin <tag> to install one (or a non-semver tag)", redactURL(repoURL))
77			}
78			if len(tags) > maxTagFallbacks {
79				tags = tags[:maxTagFallbacks]
80			}
81		}
82	
83		var lastErr error
84		for i, tag := range tags {
85			res, err := installRepoAtTag(ctx, repoURL, tag, opts)
86			if err == nil {
87				res.SkippedTags = tags[:i]
88				return res, nil
89			}
90			lastErr = err
91			if !errors.Is(err, errAssetNotFound) {
92				return nil, err
93			}
94		}
95		return nil, lastErr
96	}
97	
98	func installRepoAtTag(ctx context.Context, repoURL, tag string, opts RemoteInstallOptions) (*RemoteInstallResult, error) {
99		meta, err := fetchPluginMetadataAtTag(ctx, repoURL, tag)
100		if err != nil {
101			return nil, err
102		}
103		// The installed name comes from the *remote* — entire-plugin.yml's name:,
104		// else the repo basename.
105		var name string
106		if meta != nil && meta.Name != "" {
107			name = meta.Name
108		} else if name, err = pluginNameFromRepoURL(repoURL); err != nil {
109			return nil, err
110		}
111	
112		// Reconcile it with what the caller asked for. Unchecked, the remote chose
113		// the name unilaterally, which broke three things:
114		//
115		//  - `install <index-name>` could install something else entirely: the
116		//    index entry says "safe", the repo declares "hijack", and the user gets
117		//    entire-hijack on PATH with no prompt (index installs never prompt).
118		//  - --force escalated across plugins: the already-installed check below
119		//    tests the *remote-declared* name, so reinstalling A let A's repo
120		//    declare name: B and replace an unrelated installed B.
121		//  - A dependency installed under a different name never satisfied the
122		//    requirement, so dependencySatisfied/doctor reported it missing forever
123		//    and every future parent install re-attempted it.
124		//
125		// Fatal rather than a warning: every caller that sets ExpectedName has
126		// already made a trust decision about *that* name, and silently honoring a
127		// different one voids it. A legitimate rename is a catalog or requirement
128		// to fix, and the message says so.
129		if opts.ExpectedName != "" && name != opts.ExpectedName {
130			return nil, fmt.Errorf(
131				"%s declares plugin name %q but %q was requested; refusing to install under a name that was not asked for (update the plugin index entry or the requirement if the plugin was renamed)",
132				redactURL(repoURL), name, opts.ExpectedName)
133		}
134	
135		if existing, err := FindInstalledPlugin(name); err != nil {
136			return nil, err
137		} else if existing != nil && !opts.Force {
138			return nil, fmt.Errorf("plugin %q already installed at %s; use --force to replace", name, existing.Path)
139		}
140	
141		staging, err := os.MkdirTemp("", "entire-plugin-fetch-")
142		if err != nil {
143			return nil, fmt.Errorf("create staging dir: %w", err)
144		}
145		defer os.RemoveAll(staging)
146	
147		asset, err := downloadPluginAsset(ctx, meta, repoURL, name, tag, staging, opts.AllowUnverified)
148		if err != nil {
149			return nil, err
150		}
151	
152		binBase := pluginBinaryName(name)
153		stagedBin := filepath.Join(staging, "extracted-"+binBase)
154		if err := extractPluginBinary(asset.Path, name, stagedBin); err != nil {
155			return nil, err
156		}
157	
158		pkgDir, err := EnsurePluginPkgDir(name)
159		if err != nil {
160			return nil, err
161		}
162		sweepOldBinaries(pkgDir)
163		pkgBin := filepath.Join(pkgDir, binBase)
164		if err := replaceBinary(stagedBin, pkgBin); err != nil {
165			return nil, fmt.Errorf("place plugin binary: %w", err)
166		}
167	
168		// Digest the binary we actually placed, not just the archive it came from.
169		// asset.SHA256 covers the downloaded asset, which is discarded with the
170		// staging dir — so it records provenance but can never detect later
171		// tampering. binDigest is what `plugin doctor` re-checks.
172		binDigest, err := fileSHA256(pkgBin)
173		if err != nil {
174			return nil, fmt.Errorf("hash installed plugin binary: %w", err)
175		}
176	
177		installed, err := InstallPluginFromPath(InstallPluginOptions{SourcePath: pkgBin, Force: true})
178		if err != nil {
179			return nil, err
180		}
181	
182		manifest := &PluginManifest{
183			Name:         name,
184			RepoURL:      repoURL,
185			Tag:          tag,
186			Asset:        asset.Asset,
187			SHA256:       asset.SHA256,
188			BinarySHA256: binDigest,
189			Unverified:   !asset.Verified,
190			Pinned:       opts.Pin != "",
191			InstalledAt:  time.Now().UTC(),
192		}
193		if meta != nil {
194			manifest.Requires = meta.Requires
195		}
196		if err := SavePluginManifest(manifest); err != nil {
197			return nil, err
198		}
199		return &RemoteInstallResult{Installed: installed, Manifest: manifest, Metadata: meta}, nil
200	}
201	
202	// UpgradeOutcome describes what UpgradeInstalledPlugin did.
203	type UpgradeOutcome struct {
204		Name string
205		// Pinned: skipped because the manifest is pinned.
206		Pinned bool
207		// UpToDate: already at the newest tag.
208		UpToDate bool
209		// FromTag/ToTag are set when an upgrade actually happened.
210		FromTag, ToTag string
211	}
212	
213	// UpgradeInstalledPlugin re-resolves the newest tag for a remote-installed
214	// plugin and reinstalls when it differs from the manifest's tag. Plugins
215	// without a manifest (local-dev symlinks) are not upgradable.
216	func UpgradeInstalledPlugin(ctx context.Context, name string) (*UpgradeOutcome, error) {
217		m, err := LoadPluginManifest(name)
218		if err != nil {
219			return nil, err
220		}
221		if m == nil {
222			return nil, fmt.Errorf("plugin %q has no install manifest (local-dev install?); reinstall it from its repository URL to make it upgradable", name)
223		}
224		if m.Pinned {
225			return &UpgradeOutcome{Name: name, Pinned: true}, nil
226		}
227		tags, err := listRemoteSemverTags(ctx, m.RepoURL)
228		if err != nil {
229			return nil, err
230		}
231		if len(tags) == 0 {
232			return nil, fmt.Errorf("%s has no stable semver tags; prereleases are skipped, so pass --pin <tag> to move to one", redactURL(m.RepoURL))
233		}
234		// Semver comparison, not string equality: "v0.2.0" and "0.2.0" are the
235		// same version, and a remote that re-tagged with the other spelling
236		// must not trigger a reinstall.
237		if semver.Compare(canonicalSemver(tags[0]), canonicalSemver(m.Tag)) <= 0 {
238			return &UpgradeOutcome{Name: name, UpToDate: true}, nil
239		}
240		// Inherit the install-time trust decision: a plugin the user knowingly
241		// installed unverified shouldn't start failing on upgrade, and one
242		// installed verified must not silently downgrade to unverified.
243		res, err := InstallPluginFromRepo(ctx, RemoteInstallOptions{
244			RepoURL: m.RepoURL, Force: true, AllowUnverified: m.Unverified,
245			ExpectedName: name,
246		})
247		if err != nil {
248			return nil, err
249		}
250		// The install may have fallen back past an asset-less newest tag and
251		// landed on the version already installed — that's up-to-date, not an
252		// upgrade line claiming X → X.
253		if semver.Compare(canonicalSemver(res.Manifest.Tag), canonicalSemver(m.Tag)) <= 0 {
254			return &UpgradeOutcome{Name: name, UpToDate: true}, nil
255		}
256		return &UpgradeOutcome{Name: name, FromTag: m.Tag, ToTag: res.Manifest.Tag}, nil
257	}
258	
259	// replaceBinary moves src over dest atomically. On Windows, a running
260	// executable can't be replaced (sharing violation) but it *can* be renamed:
261	// move the old binary aside to a .old-<rand> file and retry; leftovers are
262	// swept on the next install. os.Rename fails across filesystems (staging is
263	// in the system temp dir), so a copy fallback covers that case.
264	func replaceBinary(src, dest string) error {
265		err := os.Rename(src, dest)
266		if err == nil {
267			return nil
268		}
269		if runtime.GOOS == windowsGOOS {
270			if asideErr := os.Rename(dest, oldBinaryAsidePath(dest)); asideErr == nil {
271				if err = os.Rename(src, dest); err == nil {
272					return nil
273				}
274			}
275		}
276		// Cross-device rename: copy + fsync-free write, then remove src.
277		in, openErr := os.Open(src) //nolint:gosec // staging file we created
278		if openErr != nil {
279			return errors.Join(err, openErr)
280		}
281		defer in.Close()
282		if writeErr := writeExecutable(in, dest); writeErr != nil {
283			return errors.Join(err, writeErr)
284		}
285		_ = os.Remove(src)
286		return nil
287	}
288	
289	// oldBinaryAsidePath returns a unique .old- sibling path for the
290	// rename-aside trick. Random suffix so concurrent upgrades can't collide.
291	func oldBinaryAsidePath(dest string) string {
292		var b [4]byte
293		if _, err := rand.Read(b[:]); err != nil {
294			return dest + ".old-fallback"
295		}
296		return dest + ".old-" + hex.EncodeToString(b[:])
297	}
298	
299	// sweepOldBinaries best-effort removes .old-* leftovers from the Windows
300	// rename-aside fallback. Failures are ignored — the files are inert.
301	func sweepOldBinaries(pkgDir string) {
302		entries, err := os.ReadDir(pkgDir)
303		if err != nil {
304			return
305		}
306		for _, e := range entries {
307			if strings.Contains(e.Name(), ".old-") {
308				_ = os.Remove(filepath.Join(pkgDir, e.Name()))
309			}
310		}
311	}
312	
313	// RemoveManagedPlugin removes a plugin's bin entries and its pkg dir.
314	// The dependency guard lives in the command layer so --force can bypass it.
315	func RemoveManagedPlugin(name string) error {
316		if err := RemoveInstalledPlugin(name); err != nil {
317			return err
318		}
319		return RemovePluginPkg(name)
320	}
