	"golang.org/x/mod/semver"
)

// Remote install orchestration: resolve tag → fetch metadata → download +
// verify + extract → place under pkg/<name>/ → link into bin/ → write
// manifest. The bin/ link goes through the same InstallPluginFromPath used
// by local-dev installs, so conflict handling, atomic replace, and the
// Windows symlink fallbacks are shared, not duplicated.

// maxTagFallbacks bounds how many tags we walk down when the newest tag has
// no published assets (tag pushed, release not finished).
const maxTagFallbacks = 3

// RemoteInstallOptions configures InstallPluginFromRepo.
type RemoteInstallOptions struct {
	// RepoURL is the full git URL of the plugin repository.
	RepoURL string
	// Pin, when non-empty, installs exactly this tag and marks the
	// manifest pinned so upgrade skips it.
	Pin string
	// Force replaces an existing managed entry with the same name.
	Force bool
	// AllowUnverified permits installing a release that publishes no
	// checksums.txt covering this platform. Off by default: downloading and
	// executing an unauthenticated binary is the supply-chain risk the
	// checksum path exists to remove, so it takes an explicit opt-in.
	AllowUnverified bool
	// ExpectedName is the plugin name the caller has already committed to —
	// the index entry the user asked for, the requirement being satisfied, or
	// the plugin being upgraded. Empty only when the caller genuinely has no
	// expectation, i.e. a bare `install <url>` where the repository names
	// itself. See installRepoAtTag for why a mismatch is fatal.
	ExpectedName string
}

// RemoteInstallResult is what a successful remote install produced.
type RemoteInstallResult struct {
	Installed *InstalledPlugin
	Manifest  *PluginManifest
	Metadata  *PluginMetadata
	// SkippedTags lists newer tags that were passed over for missing
	// assets, newest first. Callers surface these as warnings.
	SkippedTags []string
}

// InstallPluginFromRepo installs a plugin from a git repository URL.
// Dependency resolution deliberately does not happen here — callers
// (the install command) plan and confirm dependency installs first.
func InstallPluginFromRepo(ctx context.Context, opts RemoteInstallOptions) (*RemoteInstallResult, error) {
	repoURL := strings.TrimRight(opts.RepoURL, "/")

	var tags []string
	if opts.Pin != "" {
		tags = []string{opts.Pin}
	} else {
		var err error
		tags, err = listRemoteSemverTags(ctx, repoURL)
		if err != nil {
			return nil, err
		}
		if len(tags) == 0 {
			return nil, fmt.Errorf("%s has no stable semver tags; prereleases are skipped, so pass --pin <tag> to install one (or a non-semver tag)", redactURL(repoURL))
		}
		if len(tags) > maxTagFallbacks {
			tags = tags[:maxTagFallbacks]
		}
	}

	var lastErr error
	for i, tag := range tags {
		res, err := installRepoAtTag(ctx, repoURL, tag, opts)
		if err == nil {
			res.SkippedTags = tags[:i]
			return res, nil
		}
		lastErr = err
		if !errors.Is(err, errAssetNotFound) {
			return nil, err
		}
	}
	return nil, lastErr
}

func installRepoAtTag(ctx context.Context, repoURL, tag string, opts RemoteInstallOptions) (*RemoteInstallResult, error) {
	meta, err := fetchPluginMetadataAtTag(ctx, repoURL, tag)
	if err != nil {
		return nil, err
	}
	// The installed name comes from the *remote* — entire-plugin.yml's name:,
	// else the repo basename.
	var name string
	if meta != nil && meta.Name != "" {
		name = meta.Name
	} else if name, err = pluginNameFromRepoURL(repoURL); err != nil {
		return nil, err
	}

	// Reconcile it with what the caller asked for. Unchecked, the remote chose
	// the name unilaterally, which broke three things:
	//
	//  - `install <index-name>` could install something else entirely: the
	//    index entry says "safe", the repo declares "hijack", and the user gets
	//    entire-hijack on PATH with no prompt (index installs never prompt).
	//  - --force escalated across plugins: the already-installed check below
	//    tests the *remote-declared* name, so reinstalling A let A's repo
	//    declare name: B and replace an unrelated installed B.
	//  - A dependency installed under a different name never satisfied the
	//    requirement, so dependencySatisfied/doctor reported it missing forever
	//    and every future parent install re-attempted it.
	//
	// Fatal rather than a warning: every caller that sets ExpectedName has
	// already made a trust decision about *that* name, and silently honoring a
	// different one voids it. A legitimate rename is a catalog or requirement
	// to fix, and the message says so.
	if opts.ExpectedName != "" && name != opts.ExpectedName {
		return nil, fmt.Errorf(
			"%s declares plugin name %q but %q was requested; refusing to install under a name that was not asked for (update the plugin index entry or the requirement if the plugin was renamed)",
			redactURL(repoURL), name, opts.ExpectedName)
	}

	if existing, err := FindInstalledPlugin(name); err != nil {
		return nil, err
	} else if existing != nil && !opts.Force {
		return nil, fmt.Errorf("plugin %q already installed at %s; use --force to replace", name, existing.Path)
	}

	staging, err := os.MkdirTemp("", "entire-plugin-fetch-")
	if err != nil {
		return nil, fmt.Errorf("create staging dir: %w", err)
	}
	defer os.RemoveAll(staging)

	asset, err := downloadPluginAsset(ctx, meta, repoURL, name, tag, staging, opts.AllowUnverified)
	if err != nil {
		return nil, err
	}

	binBase := pluginBinaryName(name)
	stagedBin := filepath.Join(staging, "extracted-"+binBase)
	if err := extractPluginBinary(asset.Path, name, stagedBin); err != nil {
		return nil, err
	}

	pkgDir, err := EnsurePluginPkgDir(name)
	if err != nil {
		return nil, err
	}
	sweepOldBinaries(pkgDir)
	pkgBin := filepath.Join(pkgDir, binBase)
	if err := replaceBinary(stagedBin, pkgBin); err != nil {
		return nil, fmt.Errorf("place plugin binary: %w", err)
	}

	// Digest the binary we actually placed, not just the archive it came from.
	// asset.SHA256 covers the downloaded asset, which is discarded with the
	// staging dir — so it records provenance but can never detect later
	// tampering. binDigest is what `plugin doctor` re-checks.
	binDigest, err := fileSHA256(pkgBin)
	if err != nil {
		return nil, fmt.Errorf("hash installed plugin binary: %w", err)
	}

	installed, err := InstallPluginFromPath(InstallPluginOptions{SourcePath: pkgBin, Force: true})
	if err != nil {
		return nil, err
	}

	manifest := &PluginManifest{
		Name:         name,
		RepoURL:      repoURL,
		Tag:          tag,
		Asset:        asset.Asset,
		SHA256:       asset.SHA256,
		BinarySHA256: binDigest,
		Unverified:   !asset.Verified,
		Pinned:       opts.Pin != "",
		InstalledAt:  time.Now().UTC(),
	}
	if meta != nil {
		manifest.Requires = meta.Requires
	}
	if err := SavePluginManifest(manifest); err != nil {
		return nil, err
	}
	return &RemoteInstallResult{Installed: installed, Manifest: manifest, Metadata: meta}, nil
}

// UpgradeOutcome describes what UpgradeInstalledPlugin did.
type UpgradeOutcome struct {
	Name string
	// Pinned: skipped because the manifest is pinned.
	Pinned bool
	// UpToDate: already at the newest tag.
	UpToDate bool
	// FromTag/ToTag are set when an upgrade actually happened.
	FromTag, ToTag string
}

// UpgradeInstalledPlugin re-resolves the newest tag for a remote-installed
// plugin and reinstalls when it differs from the manifest's tag. Plugins
// without a manifest (local-dev symlinks) are not upgradable.
func UpgradeInstalledPlugin(ctx context.Context, name string) (*UpgradeOutcome, error) {
	m, err := LoadPluginManifest(name)
	if err != nil {
		return nil, err
	}
	if m == nil {
		return nil, fmt.Errorf("plugin %q has no install manifest (local-dev install?); reinstall it from its repository URL to make it upgradable", name)
	}
	if m.Pinned {
		return &UpgradeOutcome{Name: name, Pinned: true}, nil
	}
	tags, err := listRemoteSemverTags(ctx, m.RepoURL)
	if err != nil {
		return nil, err
	}
	if len(tags) == 0 {
		return nil, fmt.Errorf("%s has no stable semver tags; prereleases are skipped, so pass --pin <tag> to move to one", redactURL(m.RepoURL))
	}
	// Semver comparison, not string equality: "v0.2.0" and "0.2.0" are the
	// same version, and a remote that re-tagged with the other spelling
	// must not trigger a reinstall.
	if semver.Compare(canonicalSemver(tags[0]), canonicalSemver(m.Tag)) <= 0 {
		return &UpgradeOutcome{Name: name, UpToDate: true}, nil
	}
	// Inherit the install-time trust decision: a plugin the user knowingly
	// installed unverified shouldn't start failing on upgrade, and one
	// installed verified must not silently downgrade to unverified.
	res, err := InstallPluginFromRepo(ctx, RemoteInstallOptions{
		RepoURL: m.RepoURL, Force: true, AllowUnverified: m.Unverified,
		ExpectedName: name,
	})
	if err != nil {
		return nil, err
	}
	// The install may have fallen back past an asset-less newest tag and
	// landed on the version already installed — that's up-to-date, not an
	// upgrade line claiming X → X.
	if semver.Compare(canonicalSemver(res.Manifest.Tag), canonicalSemver(m.Tag)) <= 0 {
		return &UpgradeOutcome{Name: name, UpToDate: true}, nil
	}
	return &UpgradeOutcome{Name: name, FromTag: m.Tag, ToTag: res.Manifest.Tag}, nil
}

// replaceBinary moves src over dest atomically. On Windows, a running
// executable can't be replaced (sharing violation) but it *can* be renamed:
// move the old binary aside to a .old-<rand> file and retry; leftovers are
// swept on the next install. os.Rename fails across filesystems (staging is
// in the system temp dir), so a copy fallback covers that case.
func replaceBinary(src, dest string) error {
	err := os.Rename(src, dest)
	if err == nil {
		return nil
	}
	if runtime.GOOS == windowsGOOS {
		if asideErr := os.Rename(dest, oldBinaryAsidePath(dest)); asideErr == nil {
			if err = os.Rename(src, dest); err == nil {
				return nil
			}
		}
	}
	// Cross-device rename: copy + fsync-free write, then remove src.
	in, openErr := os.Open(src) //nolint:gosec // staging file we created
	if openErr != nil {
		return errors.Join(err, openErr)
	}
	defer in.Close()
	if writeErr := writeExecutable(in, dest); writeErr != nil {
		return errors.Join(err, writeErr)
	}
	_ = os.Remove(src)
	return nil
}

// oldBinaryAsidePath returns a unique .old- sibling path for the
// rename-aside trick. Random suffix so concurrent upgrades can't collide.
func oldBinaryAsidePath(dest string) string {
	var b [4]byte
	if _, err := rand.Read(b[:]); err != nil {
		return dest + ".old-fallback"
	}
	return dest + ".old-" + hex.EncodeToString(b[:])
}

// sweepOldBinaries best-effort removes .old-* leftovers from the Windows
// rename-aside fallback. Failures are ignored — the files are inert.
func sweepOldBinaries(pkgDir string) {
	entries, err := os.ReadDir(pkgDir)
	if err != nil {
		return
	}
	for _, e := range entries {
		if strings.Contains(e.Name(), ".old-") {
			_ = os.Remove(filepath.Join(pkgDir, e.Name()))
		}
	}
}

// RemoveManagedPlugin removes a plugin's bin entries and its pkg dir.
// The dependency guard lives in the command layer so --force can bypass it.
func RemoveManagedPlugin(name string) error {
	if err := RemoveInstalledPlugin(name); err != nil {
		return err
	}
	return RemovePluginPkg(name)
}

package cli

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"time"

	"gopkg.in/yaml.v3"
)

// Managed-install manifests. A plugin installed from a remote repository
// gets a per-plugin home under the managed dir:
//
//	<plugin-root>/pkg/<name>/entire-<name>[.exe]   the binary
//	<plugin-root>/pkg/<name>/manifest.yml          install provenance
//
// The bin/ dir remains the only dispatch surface — pkg/ binaries are
// linked into bin/ via the same symlink→hardlink→copy fallback as local
// installs, so the kubectl-style resolver in plugin.go never changes.
//
// Local-dev installs (`entire plugin install ./path`) bypass pkg/ entirely
// and have no manifest; ListPluginManifests simply doesn't see them.
const (
	pluginManagedPkgSubdir = "pkg"
	pluginManifestFileName = "manifest.yml"
	// windowsExeExt is the extension Windows executables need.
	windowsExeExt = ".exe"
)

// pluginBinaryName returns the on-disk executable name for a bare plugin
// name: entire-<name>, plus the Windows extension where the host needs it.
func pluginBinaryName(name string) string {
	if runtime.GOOS == windowsGOOS {
		return pluginBinaryPrefix + name + windowsExeExt
	}
	return pluginBinaryPrefix + name
}

// PluginManifest records how a managed plugin was installed. Settings
// configure behavior; manifests record facts. The dependency list is
// copied from the plugin's metadata at install time so reverse-dependency
// checks (remove guard, doctor) work offline.
type PluginManifest struct {
	// Name is the bare plugin name ("run" for entire-run).
	Name string `yaml:"name"`
	// RepoURL is the full git URL the plugin was installed from.
	RepoURL string `yaml:"repo_url"`
	// Tag is the git tag that was installed (e.g. "v0.2.1").
	Tag string `yaml:"tag"`
	// Asset is the release asset filename the binary came from. Empty for
	// raw-binary downloads where the asset name equals the binary name.
	Asset string `yaml:"asset,omitempty"`
	// SHA256 is the hex digest of the downloaded asset.
	SHA256 string `yaml:"sha256,omitempty"`
	// BinarySHA256 is the hex digest of the installed binary under
	// pkg/<name>/. Distinct from SHA256, which covers the downloaded asset —
	// usually an archive, and discarded with the staging dir. Recording the
	// binary is what lets `plugin doctor` detect post-install tampering.
	BinarySHA256 string `yaml:"binary_sha256,omitempty"`
	// Unverified records that no checksum manifest authenticated the
	// download (installed with --allow-unverified). Surfaced by doctor.
	Unverified bool `yaml:"unverified,omitempty"`
	// Pinned marks installs done with --pin; upgrade skips them.
	Pinned bool `yaml:"pinned,omitempty"`
	// InstalledAt is when the install (or last upgrade) completed.
	InstalledAt time.Time `yaml:"installed_at,omitempty"`
	// Requires is the dependency list from the plugin's entire-plugin.yml
	// at the installed tag.
	Requires []PluginRequirement `yaml:"requires,omitempty"`
}

// PluginRequirement declares a dependency on another plugin. Shared between
// the author-side metadata file (entire-plugin.yml) and the install-side
// manifest so the two can never drift.
//
// There is deliberately no repo_url. A missing dependency resolves by name
// through the plugin index, so the URL a dependency install fetches from always
// comes from the curated catalog rather than from the requiring plugin's author.
// With an author-supplied URL, installing one plugin meant fetching and
// executing a binary from a URL its author chose — and dependency planning
// contacted that URL *before* the confirmation prompt. The capability is not
// gone, the authority moved: a user can still install an out-of-catalog
// dependency by URL themselves, with the usual untrusted-source prompt, after
// which the requirement is satisfied. Consent belongs to the user, not the
// author.
//
// A dependency must therefore be indexed before a dependent can ship, the same
// constraint krew, Homebrew and apt impose.
type PluginRequirement struct {
	// Name is the bare plugin name of the dependency, resolved through the
	// plugin index.
	Name string `yaml:"name"`
	// MinVersion is the minimum acceptable tag (e.g. "v0.2.0"). Minimum
	// only — there is deliberately no range syntax.
	MinVersion string `yaml:"min_version,omitempty"`
}

// PluginMetadata is the author-side declaration committed at the root of a
// plugin repository as entire-plugin.yml. Everything is optional — a repo
// without the file installs fine; the name then derives from the repo URL.
type PluginMetadata struct {
	// Name is the bare plugin name. When empty, derived from the repo URL
	// basename (entire-run → run).
	Name string `yaml:"name,omitempty"`
	// Description is a one-line summary shown by info/search.
	Description string `yaml:"description,omitempty"`
	// DownloadURL overrides the per-forge release-asset URL convention.
	// Template placeholders: {name} {tag} {version} {os} {arch} {asset}.
	// When {asset} is present, candidate asset filenames are substituted;
	// otherwise the expanded template is fetched as-is.
	DownloadURL string `yaml:"download_url,omitempty"`
	// Requires lists plugins this plugin needs at runtime.
	Requires []PluginRequirement `yaml:"requires,omitempty"`
}

// pluginMetadataFileName is the well-known path of the author-side metadata
// file at the root of a plugin repository.
const pluginMetadataFileName = "entire-plugin.yml"

// ParsePluginMetadata decodes entire-plugin.yml content.
//
// Decoding is lenient: unknown keys are ignored, matching the choice made for
// index.json. Both are artifacts read by every CLI version ever shipped, and
// refusing one an older binary doesn't fully understand breaks it permanently
// for everyone on that version — the plugin author cannot fix it for them.
// entire-plugin.yml has no version field to gate on either, so the first author
// to adopt any future field (min_cli_version, bin_name, …) would break installs
// on every older CLI.
//
// This deliberately gives up catching author typos here, which strict decoding
// did. The trade is asymmetric: a misspelled key costs the author one confused
// test run against their own plugin, while a forward-compatibility break is
// unfixable and fleet-wide. Author-side validation belongs in a lint command,
// not in the hot path every user's install runs through.
func ParsePluginMetadata(data []byte) (*PluginMetadata, error) {
	var meta PluginMetadata
	dec := yaml.NewDecoder(bytes.NewReader(data))
	if err := dec.Decode(&meta); err != nil {
		// An empty or comment-only stream decodes to io.EOF. The file is
		// documented as optional and a *missing* one is fine, so a committed
		// placeholder must not be fatal at every tag. An explicit "---" already
		// behaved this way; align the empty cases with it.
		if !errors.Is(err, io.EOF) {
			return nil, fmt.Errorf("parsing %s: %w", pluginMetadataFileName, err)
		}
		meta = PluginMetadata{}
	}
	if meta.Name != "" {
		if err := validatePluginName(meta.Name); err != nil {
			return nil, fmt.Errorf("%s declares invalid name: %w", pluginMetadataFileName, err)
		}
	}
	for _, req := range meta.Requires {
		if err := validatePluginName(req.Name); err != nil {
			return nil, fmt.Errorf("%s declares invalid requirement: %w", pluginMetadataFileName, err)
		}
	}
	return &meta, nil
}

// PluginPkgDir returns the per-plugin package directory for the given bare
// name. Not created — callers use EnsurePluginPkgDir when writing.
func PluginPkgDir(name string) (string, error) {
	if err := validatePluginName(name); err != nil {
		return "", err
	}
	parent, err := pluginParentDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(parent, pluginManagedPkgSubdir, name), nil
}

// EnsurePluginPkgDir creates the package directory for name.
func EnsurePluginPkgDir(name string) (string, error) {
	dir, err := PluginPkgDir(name)
	if err != nil {
		return "", err
	}
	if err := os.MkdirAll(dir, 0o750); err != nil {
		return "", fmt.Errorf("create plugin pkg dir: %w", err)
	}
	return dir, nil
}

// LoadPluginManifest reads the manifest for name. Returns (nil, nil) when
// the plugin has no manifest — local-dev installs and raw-PATH plugins.
func LoadPluginManifest(name string) (*PluginManifest, error) {
	dir, err := PluginPkgDir(name)
	if err != nil {
		return nil, err
	}
	data, err := os.ReadFile(filepath.Join(dir, pluginManifestFileName)) //nolint:gosec // path is inside the managed pkg tree
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil //nolint:nilnil // no-manifest signal
		}
		return nil, fmt.Errorf("read plugin manifest: %w", err)
	}
	var m PluginManifest
	if err := yaml.Unmarshal(data, &m); err != nil {
		return nil, fmt.Errorf("parse plugin manifest for %q: %w", name, err)
	}
	return &m, nil
}

// SavePluginManifest writes the manifest into the plugin's pkg dir.
func SavePluginManifest(m *PluginManifest) error {
	// Strip any credentials before persisting: manifest.yml is mode 0644 and a
	// token in a remote URL has no business on disk. Upgrades re-resolve the
	// remote through git's credential helpers, which is where auth belongs.
	m.RepoURL = redactURL(m.RepoURL)
	dir, err := EnsurePluginPkgDir(m.Name)
	if err != nil {
		return err
	}
	data, err := yaml.Marshal(m)
	if err != nil {
		return fmt.Errorf("marshal plugin manifest: %w", err)
	}
	path := filepath.Join(dir, pluginManifestFileName)
	if err := os.WriteFile(path, data, 0o644); err != nil { //nolint:gosec // manifest is non-secret provenance metadata
		return fmt.Errorf("write plugin manifest: %w", err)
	}
	return nil
}

// ListPluginManifests returns the manifests of every remote-installed
// plugin, sorted by name. Pkg entries without a readable manifest are
// skipped — a half-removed plugin shouldn't break listing.
func ListPluginManifests() ([]*PluginManifest, error) {
	parent, err := pluginParentDir()
	if err != nil {
		return nil, err
	}
	entries, err := os.ReadDir(filepath.Join(parent, pluginManagedPkgSubdir))
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, fmt.Errorf("read plugin pkg dir: %w", err)
	}
	var out []*PluginManifest
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		m, err := LoadPluginManifest(e.Name())
		if err != nil || m == nil {
			continue
		}
		out = append(out, m)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out, nil
}

// RemovePluginPkg deletes the plugin's pkg dir (binary + manifest).
// Missing dir is not an error — local-dev installs never had one.
func RemovePluginPkg(name string) error {
	dir, err := PluginPkgDir(name)
	if err != nil {
		return err
	}
	if err := os.RemoveAll(dir); err != nil {
		return fmt.Errorf("remove plugin pkg dir: %w", err)
	}
	return nil
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"runtime"
	"slices"
	"strings"

	"charm.land/huh/v2"
	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/spf13/cobra"
)

// newPluginGroupCmd builds `entire plugin` and its subcommands. The kubectl
// dispatcher in plugin.go is the runtime mechanism — these commands manage a
// per-user managed directory that the dispatcher discovers because main.go
// prepends it to PATH at startup.
func newPluginGroupCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "plugin",
		Short: "Manage Entire plugins (install, list, upgrade, search, remove)",
		Long: `Manage Entire plugins.

Plugins are external executables named 'entire-<name>'. The CLI discovers
plugins on $PATH and from a per-user managed directory which is
auto-prepended to PATH at startup. The managed directory is, in order of
precedence:

  $ENTIRE_PLUGIN_DIR/bin (override)
  $XDG_DATA_HOME/entire/plugins/bin (Linux/macOS, when set)
  ~/.local/share/entire/plugins/bin (Linux/macOS default)
  %LOCALAPPDATA%\entire\plugins\bin (Windows, when set)
  ~\AppData\Local\entire\plugins\bin (Windows fallback when LOCALAPPDATA is unset)

Install sources:
  entire plugin install run                                    index lookup
  entire plugin install https://github.com/entireio/entire-run repository URL
  entire plugin install ./dist/entire-run                      local executable

Remote installs resolve the newest semver tag over the git protocol, then
download the platform's release asset (verified against the release's
checksums.txt when published). Discovery uses a git-synced plugin index;
see 'entire plugin search' and 'entire plugin index update'.`,
	}

	cmd.AddCommand(newPluginInstallCmd())
	cmd.AddCommand(newPluginListCmd())
	cmd.AddCommand(newPluginRemoveCmd())
	cmd.AddCommand(newPluginUpgradeCmd())
	cmd.AddCommand(newPluginSearchCmd())
	cmd.AddCommand(newPluginInfoCmd())
	cmd.AddCommand(newPluginBrowseCmd())
	cmd.AddCommand(newPluginDoctorCmd())
	cmd.AddCommand(newPluginIndexCmd())
	return cmd
}

// installArgKind classifies the install argument.
type installArgKind int

const (
	installFromPath installArgKind = iota
	installFromURL
	installFromIndex
)

// classifyInstallArg distinguishes the three install sources. URLs are
// anything with a scheme or scp-like git@ prefix; paths must be explicit —
// a separator or a leading dot (./entire-foo) — and everything else is a
// bare name for index lookup. Deliberately NOT stat-based: a stray file or
// directory in the CWD sharing a plugin's name must not shadow the index
// (and could never install anyway — path installs require an entire-
// basename). The spaces stay disjoint because validatePluginName rejects
// separators in plugin names.
func classifyInstallArg(arg string) installArgKind {
	if strings.Contains(arg, "://") || strings.HasPrefix(arg, "git@") {
		return installFromURL
	}
	if strings.ContainsAny(arg, `/\`) || strings.HasPrefix(arg, ".") {
		return installFromPath
	}
	return installFromIndex
}

func newPluginInstallCmd() *cobra.Command {
	var force, yes, noDeps, allowUnverified bool
	var pin, indexFlag string
	cmd := &cobra.Command{
		Use:   "install <name|url|path>",
		Short: "Install a plugin from the index, a git repository URL, or a local executable",
		Long: `Install a plugin.

Three source forms:

  name   Bare names resolve through the plugin index:
             entire plugin install run
  url    Full git repository URLs install from any git host. The newest
         semver tag is resolved with 'git ls-remote'; the platform's release
         asset is downloaded over HTTPS and verified against the release's
         checksums.txt. A release that publishes no checksums is refused
         unless --allow-unverified is passed:
             entire plugin install https://github.com/entireio/entire-run
  path   Local executables are linked into the managed directory (symlink
         first, so rebuilds are picked up immediately). Paths must be
         explicit — a separator or leading ./ — so a stray local file can
         never shadow an index name:
             entire plugin install ./dist/entire-run
             entire plugin install ./entire-run

Installing from a URL that is not listed in the plugin index asks for
confirmation; pass --yes to skip (required in non-interactive runs).

Plugins may declare dependencies in entire-plugin.yml. Missing dependencies
are listed and installed after a single confirmation (or with --yes);
--no-deps opts out.`,
		Args: cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			arg := args[0]

			if classifyInstallArg(arg) == installFromPath {
				p, err := InstallPluginFromPath(InstallPluginOptions{SourcePath: arg, Force: force})
				if err != nil {
					return fmt.Errorf("install plugin: %w", err)
				}
				fmt.Fprintf(cmd.OutOrStdout(), "Installed plugin %q → %s\n", p.Name, p.Path)
				warnIfShadowsBuiltin(cmd, p.Name)
				return nil
			}
			return silencePluginCancel(ctx, runRemoteInstall(ctx, cmd, arg, remoteInstallFlags{
				force: force, yes: yes, noDeps: noDeps, allowUnverified: allowUnverified,
				pin: pin, index: indexFlag,
			}))
		},
	}
	cmd.Flags().BoolVar(&force, "force", false, "Replace an existing entry with the same name")
	cmd.Flags().BoolVar(&yes, "yes", false, "Skip confirmation prompts (non-index sources, dependency installs)")
	cmd.Flags().BoolVar(&noDeps, "no-deps", false, "Do not install declared dependencies")
	cmd.Flags().StringVar(&pin, "pin", "", "Install exactly this tag and skip it during 'plugin upgrade'")
	addIndexFlag(cmd, &indexFlag)
	cmd.Flags().BoolVar(&allowUnverified, "allow-unverified", false,
		"Install even when the release publishes no "+checksumsFileName+" to authenticate the download")
	return cmd
}

// addIndexFlag registers --index on cmd. Five subcommands accept it; the help
// text lived in five places before this.
func addIndexFlag(cmd *cobra.Command, target *string) {
	cmd.Flags().StringVar(target, "index", "",
		"Plugin index URL (overrides "+pluginIndexEnvVar+" and the built-in default)")
}

type remoteInstallFlags struct {
	force, yes, noDeps, allowUnverified bool
	pin, index                          string
}

func runRemoteInstall(ctx context.Context, cmd *cobra.Command, arg string, flags remoteInstallFlags) error {
	out, errOut := cmd.OutOrStdout(), cmd.ErrOrStderr()

	repoURL := arg
	var trusted bool
	var expectedName string

	// Both paths need the catalog: one to resolve a name, the other for the
	// trust check. Sync once. An unreachable index is fatal only for the
	// name-resolution path; a URL install degrades to "not listed".
	idx, idxErr := SyncPluginIndex(ctx, resolvePluginIndexURL(flags.index), false)

	if classifyInstallArg(arg) == installFromIndex {
		if idxErr != nil {
			return fmt.Errorf("resolve %q via plugin index: %w", arg, idxErr)
		}
		entry := idx.Find(arg)
		if entry == nil {
			// Bare names never resolve to local files (see
			// classifyInstallArg), but a user who typed one expecting a
			// path install deserves the pointer.
			if _, statErr := os.Stat(arg); statErr == nil {
				return fmt.Errorf("plugin %q is not in the index; to install the local file, use an explicit path: entire plugin install ./%s", arg, arg)
			}
			return fmt.Errorf("plugin %q is not in the index; pass the repository URL to install from a specific repo (try 'entire plugin search %s')", arg, arg)
		}
		if len(entry.Platforms) > 0 && !slices.Contains(entry.Platforms, runtime.GOOS) {
			fmt.Fprintf(errOut, "Warning: index lists %q for %s only; this is %s — continuing anyway.\n",
				arg, strings.Join(entry.Platforms, "/"), runtime.GOOS)
		}
		repoURL = entry.RepoURL
		// The user asked for this catalog name; the repo must not install
		// under a different one. Index installs never prompt, so this is the
		// only thing tying the request to what lands on PATH.
		expectedName = entry.Name
		trusted = true
	} else {
		trusted = idxErr == nil && idx.HasRepoURL(repoURL)
	}

	if !trusted {
		ok, err := confirmPluginAction(ctx,
			fmt.Sprintf("Install from %s? The repository is not listed in the plugin index.", redactURL(repoURL)),
			flags.yes)
		switch {
		case errors.Is(err, errConfirmNeedsTerminal):
			return err // untrusted source can't proceed unconfirmed
		case err != nil:
			// Ctrl+C/Esc in the prompt prints "Install cancelled." and
			// exits cleanly; real prompt failures surface wrapped.
			return handleFormCancellation(out, "Install", err)
		case !ok:
			// Same outcome as an abort: nothing installed, clean exit.
			// Exit codes must not differ between Esc and answering "No" —
			// and automation never reaches this prompt at all (the
			// non-interactive path fails above with the --yes hint).
			fmt.Fprintln(out, "Install cancelled.")
			return nil
		}
	}

	res, err := InstallPluginFromRepo(ctx, RemoteInstallOptions{
		RepoURL: repoURL, Pin: flags.pin, Force: flags.force, AllowUnverified: flags.allowUnverified,
		ExpectedName: expectedName,
	})
	if err != nil {
		return fmt.Errorf("install plugin: %w", err)
	}
	for _, t := range res.SkippedTags {
		fmt.Fprintf(errOut, "Warning: tag %s has no release asset for this platform; fell back to %s.\n", t, res.Manifest.Tag)
	}
	fmt.Fprintf(out, "Installed plugin %q %s from %s\n", res.Manifest.Name, res.Manifest.Tag, redactURL(repoURL))
	if res.Manifest.Unverified {
		fmt.Fprintf(errOut, "Warning: %s published no %s; the download was not authenticated.\n", res.Manifest.Tag, checksumsFileName)
	}
	warnIfShadowsBuiltin(cmd, res.Manifest.Name)

	if flags.noDeps || res.Metadata == nil || len(res.Metadata.Requires) == 0 {
		return nil
	}
	return installPlannedDeps(ctx, cmd, res.Metadata.Requires, idx, flags)
}

// installPlannedDeps plans, confirms once (apt-style), and executes
// dependency installs. The main plugin is already installed at this point,
// so a declined or non-confirmable plan degrades to a warning, not an
// error — doctor reports the gap afterwards.
func installPlannedDeps(ctx context.Context, cmd *cobra.Command, reqs []PluginRequirement, idx *PluginIndex, flags remoteInstallFlags) error {
	out, errOut := cmd.OutOrStdout(), cmd.ErrOrStderr()
	plan, err := PlanDependencyInstalls(ctx, reqs, idx)
	if err != nil {
		return fmt.Errorf("resolve dependencies: %w", err)
	}
	for _, w := range plan.Warnings {
		fmt.Fprintf(errOut, "Warning: %s\n", w)
	}
	if len(plan.Actions) == 0 {
		return nil
	}

	// No trust annotation per entry: a missing dependency resolves only
	// through the index, and an upgrade reinstalls from the source the user
	// already accepted at that plugin's own install time. There is no longer a
	// path by which an author-chosen URL can appear in this list.
	fmt.Fprintf(out, "\nThis plugin requires %d additional plugin(s):\n", len(plan.Actions))
	for _, a := range plan.Actions {
		switch {
		case a.Upgrade:
			fmt.Fprintf(out, "  %s  (installed %s, needs >= %s — will upgrade from %s)\n",
				a.Name, a.CurrentTag, a.MinVersion, redactURL(a.RepoURL))
		default:
			fmt.Fprintf(out, "  %s  (%s)\n", a.Name, redactURL(a.RepoURL))
		}
	}
	ok, err := confirmPluginAction(ctx, "Install them now?", flags.yes)
	switch {
	case errors.Is(err, errConfirmNeedsTerminal):
		// Non-interactive without --yes: the main install already
		// succeeded, so skip with a pointer instead of failing late.
		fmt.Fprintln(errOut, "Skipping dependency installs (no terminal for confirmation; re-run with --yes). 'entire plugin doctor' will report what's missing.")
		return nil
	case err != nil:
		// User abort prints "Dependency install cancelled." and falls
		// through to the skip note; real prompt failures are returned —
		// claiming "skipped" for an error the user never saw would be
		// misreporting.
		if cancelErr := handleFormCancellation(errOut, "Dependency install", err); cancelErr != nil {
			return cancelErr
		}
		fmt.Fprintln(errOut, "'entire plugin doctor' will report what's missing.")
		return nil
	case !ok:
		fmt.Fprintln(errOut, "Skipping dependency installs; 'entire plugin doctor' will report what's missing.")
		return nil
	}
	if err := ExecuteDepPlan(ctx, plan, flags.allowUnverified); err != nil {
		return err
	}
	for _, a := range plan.Actions {
		fmt.Fprintf(out, "Installed dependency %q\n", a.Name)
	}
	return nil
}

// errConfirmNeedsTerminal signals that a confirmation was required but no
// terminal is available and --yes was not passed. Callers decide whether
// that is fatal (untrusted install) or an informed skip (dependency
// installs after the main install already succeeded).
var errConfirmNeedsTerminal = errors.New("confirmation required but no terminal available; re-run with --yes")

// confirmPluginAction asks a yes/no question. assumeYes short-circuits;
// non-interactive runs without --yes return errConfirmNeedsTerminal rather
// than guessing. Prompt errors (including huh.ErrUserAborted on Ctrl+C/Esc)
// are returned raw for callers to map via handleFormCancellation.
func confirmPluginAction(ctx context.Context, prompt string, assumeYes bool) (bool, error) {
	if assumeYes {
		return true, nil
	}
	if !interactive.CanPromptInteractively() {
		return false, fmt.Errorf("%w (%s)", errConfirmNeedsTerminal, prompt)
	}
	confirmed := false
	form := NewAccessibleForm(huh.NewGroup(
		huh.NewConfirm().Title(prompt).Value(&confirmed),
	))
	if err := form.RunWithContext(ctx); err != nil {
		// %w keeps huh.ErrUserAborted reachable for handleFormCancellation.
		return false, fmt.Errorf("confirm: %w", err)
	}
	return confirmed, nil
}

// silencePluginCancel maps Ctrl+C-induced failures to a SilentError per the
// codebase convention (clean.go, session_tokens.go) — printing "context
// canceled" at a user who just interrupted a clone or download is noise.
// The ctx.Err() check matters because a killed git child surfaces as
// "signal: killed", not context.Canceled, when the cancellation raced the
// subprocess.
func silencePluginCancel(ctx context.Context, err error) error {
	if err == nil {
		return nil
	}
	if ctx.Err() != nil || errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
		return NewSilentError(err)
	}
	return err
}

// warnIfShadowsBuiltin prints a one-line note to stderr when the just-installed
// plugin name matches a built-in command. The dispatcher's resolvePlugin gates
// dispatch on rootCmd.Find, so the built-in always wins at runtime — without
// this hint, a user who installed a shadowed plugin would silently get the
// built-in and have no idea their install was inert. We mirror the dispatcher's
// help/completion priming so names like "help" surface the warning too.
func warnIfShadowsBuiltin(cmd *cobra.Command, name string) {
	root := cmd.Root()
	if root == nil {
		return
	}
	root.InitDefaultHelpCmd()
	root.InitDefaultCompletionCmd(name)
	if c, _, err := root.Find([]string{name}); err == nil && c != root {
		fmt.Fprintf(cmd.ErrOrStderr(), "Note: %q shadows the built-in command; the built-in will take precedence at runtime.\n", name)
	}
}

func newPluginListCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "list",
		Short: "List plugins installed in the managed directory",
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runPluginList(cmd.OutOrStdout())
		},
	}
}

func runPluginList(w io.Writer) error {
	plugins, err := ListInstalledPlugins()
	if err != nil {
		return fmt.Errorf("list plugins: %w", err)
	}
	dir, err := PluginBinDir()
	if err != nil {
		return fmt.Errorf("plugin bin dir: %w", err)
	}
	if len(plugins) == 0 {
		fmt.Fprintf(w, "No plugins installed in %s.\n", dir)
		fmt.Fprintln(w, "Install one with 'entire plugin install <name|url|path>', or drop an entire-<name> binary anywhere on $PATH.")
		return nil
	}
	manifestTag := map[string]string{}
	if manifests, err := ListPluginManifests(); err == nil {
		for _, m := range manifests {
			tag := m.Tag
			if m.Pinned {
				tag += " (pinned)"
			}
			manifestTag[m.Name] = tag
		}
	}
	fmt.Fprintf(w, "Managed plugin directory: %s\n\n", dir)
	for _, p := range plugins {
		tag := manifestTag[p.Name]
		if p.Symlink {
			fmt.Fprintf(w, "  %-20s %-18s → %s\n", p.Name, tag, p.LinkTarget)
		} else {
			fmt.Fprintf(w, "  %-20s %-18s %s\n", p.Name, tag, p.Path)
		}
	}
	return nil
}

func newPluginRemoveCmd() *cobra.Command {
	var force bool
	cmd := &cobra.Command{
		Use:   "remove <name>",
		Short: "Remove a plugin from the managed directory",
		Long: `Remove a plugin from the managed directory.

Only entries in the managed directory are affected. Plugins installed by
dropping a binary elsewhere on $PATH are unmanaged — remove those by hand.

When other installed plugins declare the target as a dependency, removal
is refused unless --force is given.`,
		Args: cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			name := args[0]
			if !force {
				dependents, err := DependentsOf(name)
				if err != nil {
					return err
				}
				if len(dependents) > 0 {
					return fmt.Errorf("plugin %q is required by %s; use --force to remove anyway", name, strings.Join(dependents, ", "))
				}
			}
			if err := RemoveManagedPlugin(name); err != nil {
				return fmt.Errorf("remove plugin: %w", err)
			}
			fmt.Fprintf(cmd.OutOrStdout(), "Removed plugin %q\n", name)
			return nil
		},
	}
	cmd.Flags().BoolVar(&force, "force", false, "Remove even when other plugins depend on it")
	return cmd
}

func newPluginUpgradeCmd() *cobra.Command {
	var all bool
	cmd := &cobra.Command{
		Use:   "upgrade [name]",
		Short: "Upgrade remote-installed plugins to their newest tag",
		Long: `Upgrade remote-installed plugins to their newest semver tag.

Only plugins installed from a repository URL or the index carry the install
manifest upgrades need; local-dev symlink installs are skipped. Plugins
installed with --pin are skipped until reinstalled without the pin.`,
		Args: cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			out := cmd.OutOrStdout()
			var names []string
			switch {
			case len(args) == 1:
				names = []string{args[0]}
			case all:
				manifests, err := ListPluginManifests()
				if err != nil {
					return err
				}
				for _, m := range manifests {
					names = append(names, m.Name)
				}
				if len(names) == 0 {
					fmt.Fprintln(out, "No upgradable plugins (none were installed from a repository).")
					return nil
				}
			default:
				return errors.New("specify a plugin name or --all")
			}
			var firstErr error
			for _, name := range names {
				o, err := UpgradeInstalledPlugin(ctx, name)
				if err != nil {
					fmt.Fprintf(cmd.ErrOrStderr(), "Upgrade %q failed: %v\n", name, err)
					if firstErr == nil {
						firstErr = err
					}
					continue
				}
				switch {
				case o.Pinned:
					fmt.Fprintf(out, "%-20s pinned, skipped\n", name)
				case o.UpToDate:
					fmt.Fprintf(out, "%-20s up to date\n", name)
				default:
					fmt.Fprintf(out, "%-20s %s → %s\n", name, o.FromTag, o.ToTag)
				}
			}
			return silencePluginCancel(ctx, firstErr)
		},
	}
	cmd.Flags().BoolVar(&all, "all", false, "Upgrade every remote-installed plugin")
	return cmd
}

func newPluginSearchCmd() *cobra.Command {
	var indexFlag string
	cmd := &cobra.Command{
		Use:   "search [term]",
		Short: "Search the plugin index",
		Args:  cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			term := ""
			if len(args) == 1 {
				term = args[0]
			}
			idx, err := SyncPluginIndex(ctx, resolvePluginIndexURL(indexFlag), false)
			if err != nil {
				return silencePluginCancel(ctx, err)
			}
			entries := idx.Search(term)
			if len(entries) == 0 {
				fmt.Fprintf(cmd.OutOrStdout(), "No plugins matching %q in the index.\n", term)
				return nil
			}
			printIndexEntries(cmd.OutOrStdout(), entries)
			return nil
		},
	}
	addIndexFlag(cmd, &indexFlag)
	return cmd
}

func printIndexEntries(w io.Writer, entries []PluginIndexEntry) {
	installedNames := map[string]bool{}
	if installed, err := ListInstalledPlugins(); err == nil {
		for _, p := range installed {
			installedNames[p.Name] = true
		}
	}
	for _, e := range entries {
		mark := " "
		if installedNames[e.Name] {
			mark = "*"
		}
		official := ""
		if e.Official {
			official = " [official]"
		}
		fmt.Fprintf(w, "%s %-20s %s%s\n", mark, e.Name, e.Description, official)
	}
	fmt.Fprintln(w, "\n* = installed. Install with 'entire plugin install <name>'.")
}

func newPluginInfoCmd() *cobra.Command {
	var indexFlag string
	cmd := &cobra.Command{
		Use:   "info <name>",
		Short: "Show index and install details for a plugin",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			name := args[0]
			out := cmd.OutOrStdout()

			entry := (*PluginIndexEntry)(nil)
			if idx, err := SyncPluginIndex(ctx, resolvePluginIndexURL(indexFlag), false); err == nil {
				entry = idx.Find(name)
			}
			m, err := LoadPluginManifest(name)
			if err != nil {
				return err
			}
			installed, err := FindInstalledPlugin(name)
			if err != nil {
				return err
			}
			if entry == nil && m == nil && installed == nil {
				return fmt.Errorf("plugin %q: not installed and not in the index", name)
			}

			fmt.Fprintf(out, "Name:        %s\n", name)
			if entry != nil {
				fmt.Fprintf(out, "Description: %s\n", entry.Description)
				fmt.Fprintf(out, "Repository:  %s\n", redactURL(entry.RepoURL))
				fmt.Fprintf(out, "Official:    %t\n", entry.Official)
				if len(entry.Platforms) > 0 {
					fmt.Fprintf(out, "Platforms:   %s\n", strings.Join(entry.Platforms, ", "))
				}
			}
			switch {
			case m != nil:
				fmt.Fprintf(out, "Installed:   %s (from %s", m.Tag, redactURL(m.RepoURL))
				if m.Pinned {
					fmt.Fprint(out, ", pinned")
				}
				fmt.Fprintln(out, ")")
				for _, r := range m.Requires {
					line := "Requires:    " + r.Name
					if r.MinVersion != "" {
						line += " >= " + r.MinVersion
					}
					fmt.Fprintln(out, line)
				}
			case installed != nil:
				fmt.Fprintf(out, "Installed:   local (%s)\n", installed.Path)
			default:
				fmt.Fprintln(out, "Installed:   no")
			}
			return nil
		},
	}
	addIndexFlag(cmd, &indexFlag)
	return cmd
}

func newPluginBrowseCmd() *cobra.Command {
	var indexFlag string
	cmd := &cobra.Command{
		Use:   "browse",
		Short: "Interactively browse the plugin index and install",
		RunE: func(cmd *cobra.Command, _ []string) error {
			ctx := cmd.Context()
			if !interactive.CanPromptInteractively() {
				return errors.New("browse needs a terminal; use 'entire plugin search' instead")
			}
			idx, err := SyncPluginIndex(ctx, resolvePluginIndexURL(indexFlag), false)
			if err != nil {
				return silencePluginCancel(ctx, err)
			}
			if len(idx.Plugins) == 0 {
				fmt.Fprintln(cmd.OutOrStdout(), "The plugin index is empty.")
				return nil
			}
			options := make([]huh.Option[string], 0, len(idx.Plugins)+1)
			for _, e := range idx.Plugins {
				label := e.Name
				if e.Description != "" {
					label = fmt.Sprintf("%s — %s", e.Name, e.Description)
				}
				options = append(options, huh.NewOption(label, e.Name))
			}
			options = append(options, huh.NewOption("(cancel)", ""))
			choice := ""
			form := NewAccessibleForm(huh.NewGroup(
				huh.NewSelect[string]().Title("Install a plugin").Options(options...).Value(&choice),
			))
			if err := form.RunWithContext(ctx); err != nil {
				return handleFormCancellation(cmd.OutOrStdout(), "Browse", err)
			}
			if choice == "" {
				return nil
			}
			return silencePluginCancel(ctx, runRemoteInstall(ctx, cmd, choice, remoteInstallFlags{index: indexFlag}))
		},
	}
	addIndexFlag(cmd, &indexFlag)
	return cmd
}

func newPluginDoctorCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "doctor",
		Short: "Check installed plugins for missing dependencies and broken entries",
		RunE: func(cmd *cobra.Command, _ []string) error {
			issues, err := RunPluginDoctor(cmd.Context())
			if err != nil {
				return err
			}
			out := cmd.OutOrStdout()
			if len(issues) == 0 {
				fmt.Fprintln(out, "All plugins healthy.")
				return nil
			}
			for _, i := range issues {
				fmt.Fprintf(out, "%s: %s\n", i.Plugin, i.Problem)
				if i.Fix != "" {
					fmt.Fprintf(out, "    fix: %s\n", i.Fix)
				}
			}
			cmd.SilenceUsage = true
			return NewSilentError(fmt.Errorf("%d plugin issue(s) found", len(issues)))
		},
	}
}

func newPluginIndexCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "index",
		Short: "Manage the plugin index",
	}
	var indexFlag string
	update := &cobra.Command{
		Use:   "update",
		Short: "Force a refresh of the plugin index",
		RunE: func(cmd *cobra.Command, _ []string) error {
			ctx := cmd.Context()
			url := resolvePluginIndexURL(indexFlag)
			idx, err := SyncPluginIndex(ctx, url, true)
			if err != nil {
				return silencePluginCancel(ctx, err)
			}
			fmt.Fprintf(cmd.OutOrStdout(), "Index %s: %d plugin(s).\n", redactURL(url), len(idx.Plugins))
			return nil
		},
	}
	addIndexFlag(update, &indexFlag)
	cmd.AddCommand(update)
	return cmd
}

